import os
import hashlib
import hmac
import time
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/data/app.db'
API_SECRET = os.environ.get('API_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_request_signature(req):
    """Verify HMAC signature for admin endpoints"""
    sig = req.headers.get('X-Request-Signature', '')
    timestamp = req.headers.get('X-Request-Timestamp', '')
    if not sig or not timestamp:
        return False
    if abs(time.time() - float(timestamp)) > 300:
        return False
    payload = f"{req.method}:{req.path}:{timestamp}:{req.get_data(as_text=True)}"
    expected = hmac.new(API_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, expected)

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports flexible querying."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')
    operator = request.args.get('op', 'eq')

    # Validate field against allowed columns
    allowed_fields = ['username', 'email', 'role', 'created_at']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query based on operator
    if operator == 'eq':
        query = f"SELECT id, username, email, role, created_at FROM users WHERE {field} = '{value}'"
    elif operator == 'like':
        query = f"SELECT id, username, email, role, created_at FROM users WHERE {field} LIKE '%{value}%'"
    elif operator == 'gt':
        query = f"SELECT id, username, email, role, created_at FROM users WHERE {field} > '{value}'"
    elif operator == 'lt':
        query = f"SELECT id, username, email, role, created_at FROM users WHERE {field} < '{value}'"
    else:
        return jsonify({'error': 'Invalid operator'}), 400

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]
        return jsonify({'users': users, 'count': len(users)})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    user = db.execute('SELECT id, username, email, role, created_at FROM users WHERE id = ?', (user_id,)).fetchone()
    if user is None:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(user))

@app.route('/api/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing required fields'}), 400
    try:
        db = get_db()
        db.execute('INSERT INTO users (username, email) VALUES (?, ?)',
                   (data['username'], data['email']))
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/api/admin/users/<int:user_id>/role', methods=['PUT'])
def update_role(user_id):
    if not verify_request_signature(request):
        return jsonify({'error': 'Unauthorized'}), 401
    data = request.get_json()
    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE id = ?', (data.get('role', 'user'), user_id))
    db.commit()
    return jsonify({'status': 'updated'})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.3.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
